INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l11',3,3,11,'Not Guilty','无罪','间接引语(转述别人的话:He said that.../He told me.../He asked whether.../He asked what...,转述时时态后移、人称与语序相应变化),外加 say vs tell 的区别与大写字母规则(专有名词/国家国籍/星期月份/句首首字母大写)(原创承载 NCE3 L11 考点·旅客被海关官员误当走私犯,''香水''其实是自制发胶)','如今海关官员大多挺宽容,但你走“无需申报”通道、其实什么也没带时,他们照样能拦下你,连老实人都会被弄得心里发虚。而老练的职业走私犯就算箱子里藏了五百块金表,也从不心慌。上个月我出国回来,一个特别爱管闲事的年轻海关官员,一看就认定我在搞名堂。“有什么要申报的吗?”他盯着我的眼睛问。“没有,”我自信地答。“介意打开这个箱子吗?”“一点也不,”我告诉他。他把箱子翻了个底朝天,我精心码好的东西转眼乱成一团。忽然他眼睛一亮——他在箱底发现一个小瓶,一把抓了过去。“香水吧?”他讽刺地问,“这个你本该申报的。香水可不免进口税。”“这不是香水,”我笑着说,“是自制发胶——我自己配的一点混合物。”不出所料,他不信。“你闻闻,”我怂恿道。他拧开盖子,把瓶子凑到鼻孔前,一股难闻的气味立刻让他确信我说的是实话。几分钟后,一名官员用粉笔在我行李上做了记号,我便清清白白地匆匆离开了。','{"q":"Listen and answer — What was the customs officer looking for?","options":["Smuggled or undeclared goods","A lost passport","A missing child","A parking spot"],"answer_index":0}'::jsonb,'{"title":"间接引语(转述别人的话) + 大写字母","intro":"①把别人说的话转述出来,叫间接引语。转述时:say/tell 后的内容,时态通常“后移”一步(is→was, have→had, make→made, will→would);人称也随之改变。②转述一般疑问句(Yes/No 问句)用 whether 或 if:He asked whether I had anything to declare。③转述特殊疑问句要保留疑问词、并把语序还原成陈述:He asked what was in the bottle / where I had bought it。④say 后面一般不直接接“人”;tell 后面要接“人”:He said that... / He told me that...。⑤大写字母:句首、人名地名、国家/国籍、星期、月份、书名等首字母要大写。","table":{"headers":["转述类型","怎么变","例子"],"rows":[["陈述句","say/tell that + 时态后移","''It is gel.'' → He said that it was gel."],["一般疑问句","ask + whether/if","''Do you...?'' → He asked whether I..."],["特殊疑问句","ask + 疑问词 + 陈述语序","''What is it?'' → He asked what it was."],["say vs tell","tell 后接人,say 不接人","He said that... / He told me that..."]]},"specialRules":[{"rule":"转述时态后移一步:一般现在→一般过去(is→was, make→made),现在完成/一般过去→过去完成(have→had, did→had done),will→would, can→could。","mark":"时态后移"},{"rule":"转述疑问句时,问句语序要还原成“陈述语序”:不是 what is it,而是 what it was;不是 did you buy,而是 you had bought。","mark":"语序还原"},{"rule":"大写字母:句首、人名(Tom)、地名/国家(Canada)、国籍语言(English)、星期(Monday)、月份(July)、书名首字母都要大写。","mark":"Capital letters"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l11',1,NULL,'These days, customs officers are usually quite tolerant, but they can still stop you in the ''Nothing to Declare'' lane and make even honest travelers feel guilty. A hardened, professional smuggler, of course, stays perfectly calm, even with a suitcase full of hidden watches.','如今海关官员大多挺宽容,但你走“无需申报”通道、其实什么也没带时,他们照样能拦下你,连老实人都会被弄得心里发虚。而老练的职业走私犯就算箱子里藏了五百块金表,也从不心慌。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l11',2,NULL,'When I flew home from a trip abroad last month, one very officious young officer clearly decided that I was up to something. ''Do you have anything to declare?'' he asked, looking me straight in the eye. ''No,'' I answered confidently.','上个月我出国回来,一个特别爱管闲事的年轻海关官员,一看就认定我在搞名堂。“有什么要申报的吗?”他盯着我的眼睛问。“没有,”我自信地答。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l11',3,NULL,'''Would you mind opening your suitcase?'' he said. ''Not at all,'' I told him. He went through my case with great care, and everything I had packed so neatly was soon in a dreadful mess.','“介意打开这个箱子吗?”“一点也不,”我告诉他。他把箱子翻了个底朝天,我精心码好的东西转眼乱成一团。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l11',4,NULL,'Suddenly his eyes lit up: he had spotted a small bottle at the bottom and pounced on it. ''Perfume, isn''t it?'' he asked sarcastically. ''You should have declared this. Perfume is not exempt from import duty.''','忽然他眼睛一亮——他在箱底发现一个小瓶,一把抓了过去。“香水吧?”他讽刺地问,“这个你本该申报的。香水可不免进口税。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l11',5,NULL,'''It isn''t perfume,'' I said with a smile. ''It''s homemade hair gel, a little mixture I make myself.'' He unscrewed the cap and lifted the bottle to his nostrils. The smell was so dreadful that he was convinced I was telling the truth, and I hurried away, innocent after all.','“这不是香水,”我笑着说,“是自制发胶——我自己配的一点混合物。”他拧开盖子,把瓶子凑到鼻孔前,一股难闻的气味立刻让他确信我说的是实话,我便清清白白地匆匆离开了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
